//! Two concrete original Sys folds over current complete selected CODE_MAPS loans.
//! DATA has no discovery/EOF authority. The existing concrete RawTree host owes both real completions.
use crate::{captured_api_pages as fund,captured_generator_budget::Budget,captured_raw_file::Config,captured_reactive_reads::Failure,captured_allow_annotations::Operation,reactive_raw_policy_pages::RawPolicyPages};
use std::{io,sync::Arc};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum Kind{Requirements,StringNames}
impl Kind{pub fn name(self)->&'static str{match self{Self::Requirements=>"sys/requirements",Self::StringNames=>"sys/dx_string_names"}}pub fn metadata(self)->&'static crate::lint::Meta{static REQUIREMENTS:std::sync::OnceLock<crate::lint::Meta>=std::sync::OnceLock::new();static NAMES:std::sync::OnceLock<crate::lint::Meta>=std::sync::OnceLock::new();match self{Self::Requirements=>REQUIREMENTS.get_or_init(||crate::dm::sys::module_metadata(&crate::dm::sys::SysModule{name:crate::allow_registry_fields::sys_requirements::SCOPE_MODULE_NAME,rules:crate::allow_registry_fields::sys_requirements::RULES,..crate::dm::sys::SysModule::DEFAULT},crate::lint::ScanKind::Tree)),Self::StringNames=>NAMES.get_or_init(||crate::dm::sys::module_metadata(&crate::dm::sys::SysModule{name:crate::allow_registry_fields::sys_dx_string_names::SCOPE_MODULE_NAME,rules:crate::allow_registry_fields::sys_dx_string_names::RULES,..crate::dm::sys::SysModule::DEFAULT},crate::lint::ScanKind::Tree))}}}
enum Facts{Requirements(Vec<(String,String)>),StringNames(crate::sys_string_names_policy::Accessors)}
struct Row{relative:String,facts:Facts}
enum Context{Requirements(crate::sys_requirements_policy::Effects),StringNames(crate::sys_string_names_policy::Accessors,crate::pat::Pat)}
struct Phase{budget:Arc<Budget>,complete:bool}impl Drop for Phase{fn drop(&mut self){if !self.complete{self.budget.keep_failed_scratch()}}}
fn oom(b:&Budget)->Failure{b.deny();Failure::Operational(io::ErrorKind::OutOfMemory.into())}
fn selected(kind:Kind,config:&Config,relative:&str)->bool{!config.policy_path_exempt(kind.name(),kind.metadata().group,relative)}
pub fn collect(pages:&dyn RawPolicyPages,kind:Kind,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<fund::ApiData,Failure>{fund::checked(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|_|oom(root))?,complete:false};let b=&phase.budget;let pending=(||{
 let mut facts=Vec::new();if !pages.for_each(&mut|relative,views|{fund::checked(b,poll)?;if !selected(kind,config,relative){return Ok(true)}let file=views.source_file()?;if relative!=file.rel{return Err("cross Sys original index path differs".into())}let mut retained=Operation{budget:b,poll};let mut temporary=Operation{budget:views.allocation_budget(root),poll};let value=match kind{Kind::Requirements=>Facts::Requirements(crate::sys_requirements_policy::effects_of_using(file,&mut retained,&mut temporary)?),Kind::StringNames=>Facts::StringNames(crate::sys_string_names_policy::file_accessors(file,&mut retained,&mut temporary)?)};fund::row(b,poll,&mut facts)?;facts.push(Row{relative:fund::own(b,poll,relative)?,facts:value});fund::checked(views.allocation_budget(root),poll)?;Ok(true)})?{return Err("cross Sys original selected index stopped before EOF".into())}
 b.charge(facts.len().checked_mul(4*std::mem::size_of::<Row>()).and_then(|n|n.checked_add(128)).ok_or_else(||oom(b))?).map_err(|_|oom(b))?;facts.sort_by(|a,b|a.relative.cmp(&b.relative));let mut control=Operation{budget:b,poll};
 let context=match kind{Kind::Requirements=>Context::Requirements(crate::sys_requirements_policy::merge(facts.iter().filter_map(|row|match &row.facts{Facts::Requirements(value)=>Some(value),_=>None}),&mut control)?),Kind::StringNames=>{let accessors=crate::sys_string_names_policy::merge(facts.iter().filter_map(|row|match &row.facts{Facts::StringNames(value)=>Some(value),_=>None}),&mut control)?;let pattern=crate::sys_string_names_policy::call_pattern_using(&accessors,&mut control)?;Context::StringNames(accessors,pattern)}};
 let mut batches=Vec::new();if !pages.for_each(&mut|relative,views|{fund::checked(b,poll)?;if !selected(kind,config,relative){return Ok(true)}let local=views.allocation_budget(root);let file=views.source_file()?;if relative!=file.rel{return Err("cross Sys original judge path differs".into())}let mut retained=Operation{budget:b,poll};let mut temporary=Operation{budget:local,poll};let mut rows=Vec::new();match &context{Context::Requirements(effects)=>{let found=crate::sys_requirements_policy::judge_using(file,effects,&mut retained,&mut temporary)?;fund::reserve_append(b,poll,&mut rows,found.len())?;for(rule,path,line)in found{fund::checked(b,poll)?;if path!=relative{return Err("cross Sys requirement finding path differs".into())}rows.push((rule,line));}},Context::StringNames(accessors,pattern)=>{if crate::sys_string_names_policy::selected(file.text()){crate::sys_string_names_policy::scan_lines_using(file,accessors,pattern,&mut rows,&mut retained,&mut temporary)?;}}}let data=crate::captured_sys_fields_pages::record_rows(views,rows,&[],&[],root,poll)?;fund::row(b,poll,&mut batches)?;batches.push((fund::own(b,poll,relative)?,data));Ok(true)})?{return Err("cross Sys original selected judge stopped before EOF".into())}
 b.charge(batches.len().checked_mul(4*std::mem::size_of::<(String,fund::ApiData)>()).and_then(|n|n.checked_add(128)).ok_or_else(||oom(b))?).map_err(|_|oom(b))?;batches.sort_by(|a,b|a.0.cmp(&b.0));let mut data=fund::empty();for(_,batch)in batches{fund::append(&mut data,batch,root,poll)?;}fund::checked(b,poll)?;Ok(data)
})();if matches!(&pending,Err(Failure::Operational(_))){return pending}fund::checked(root,poll)?;phase.complete=pending.is_ok();drop(phase);pending}
